package com.yuri.music;
import android.app.*;import android.content.*;import android.content.res.Configuration;import android.net.Uri;import android.os.*;import android.util.Rational;import android.webkit.*;import android.widget.TextView;
import androidx.webkit.*;import com.chaquo.python.Python;import org.json.*;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.nio.file.Files;import java.security.MessageDigest;import java.util.*;import java.util.concurrent.*;import java.lang.ref.WeakReference;
public class MainActivity extends Activity{
 static WeakReference<MainActivity> active=new WeakReference<>(null);AppUpdates updates;SpotifyHost spotifyHost;WebView web;File root,music,covers;WebViewAssetLoader assets;ExecutorService jobs=Executors.newFixedThreadPool(3);ConcurrentHashMap<String,String> streams=new ConcurrentHashMap<>();int cacheMB=64,dialogRequest;JSONObject dialogBody;String dialogOp;boolean destroyed;final Object diskLock=new Object();
 @Override public void onCreate(Bundle state){super.onCreate(state);active=new WeakReference<>(this);updates=new AppUpdates(this);root=getFilesDir();music=new File(root,"Music");covers=new File(getCacheDir(),"Covers");music.mkdirs();covers.mkdirs();web=new WebView(this);setContentView(web);web.setBackgroundColor(0xff000000);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setMediaPlaybackRequiresUserGesture(false);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.getSettings().setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);
 assets=new WebViewAssetLoader.Builder().setDomain("yuri.local").addPathHandler("/",new WebViewAssetLoader.AssetsPathHandler(this)).build();
 web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){return !request.getUrl().toString().equals("https://yuri.local/index.html");}@Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest request){Uri uri=request.getUrl();if(!"https".equals(uri.getScheme())||!"yuri.local".equals(uri.getHost()))return null;try{if(uri.getPath().startsWith("/stream/"))return remoteStream(request);if(uri.getPath().startsWith("/offline/")){String filename=uri.getLastPathSegment();if(!filename.matches("[A-Za-z0-9_-]{11}\\.(m4a|webm|mp4|opus)"))return null;File file=new File(music,filename);return new WebResourceResponse(filename.endsWith("webm")?"audio/webm":"audio/mp4",null,new FileInputStream(file));}}catch(Exception ignored){return new WebResourceResponse("text/plain","UTF-8",404,"Not Found",new HashMap<>(),new ByteArrayInputStream(new byte[0]));}return assets.shouldInterceptRequest(uri);}
 @Override public void onPageFinished(WebView view,String url){web.evaluateJavascript("window.yuriPlatform='android';document.querySelectorAll('#globalHotkeys,#minimizeTray,#always-top,#discord,#discordId').forEach(n=>{n.disabled=true;n.title='Disponível na versão Windows';});document.getElementById('discord-status').textContent='Presença Discord disponível no Windows.';document.getElementById('sync-folder').textContent='Escolher arquivo para sincronização';",null);}});
 web.setWebChromeClient(new WebChromeClient(){@Override public void onPermissionRequest(PermissionRequest request){request.deny();}});
 if(!WebViewFeature.isFeatureSupported(WebViewFeature.WEB_MESSAGE_LISTENER)){TextView message=new TextView(this);message.setText("Atualize o Android System WebView para abrir o Noctune.");setContentView(message);return;}
 WebViewCompat.addWebMessageListener(web,"YuriChannel",Collections.singleton("https://yuri.local"),(view,message,origin,mainFrame,reply)->{if(!mainFrame||!"https://yuri.local".equals(origin.toString()))return;try{JSONObject body=new JSONObject(message.getData());int id=body.getInt("requestId");String op=body.getString("op");if(Arrays.asList("export","import","sync-folder").contains(op)){picker(id,op,body);return;}if(op.equals("clipboard")){((ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Música",body.optString("text")));answer(id,new JSONObject().put("ok",true));return;}if(op.equals("mini")){boolean entered=enterPictureInPictureMode(new PictureInPictureParams.Builder().setAspectRatio(new Rational(2,1)).build());answer(id,new JSONObject().put("mini",entered));return;}if(op.equals("playback-status")){playback(body);answer(id,new JSONObject().put("ok",true));return;}jobs.submit(()->{try{answer(id,dispatch(body));}catch(Exception error){answerError(id,error.getMessage());}});}catch(Exception ignored){}});
 web.loadUrl("https://yuri.local/index.html");}
 static JSONObject object(String text)throws Exception{return new JSONObject(text);}JSONObject ok()throws Exception{return new JSONObject().put("ok",true);}boolean video(String id){return id.matches("[A-Za-z0-9_-]{11}");}
 JSONObject dispatch(JSONObject body)throws Exception{String op=body.getString("op");if(op.startsWith("spotify-")){if(spotifyHost==null)spotifyHost=new SpotifyHost(this);return spotifyHost.handle(body);}switch(op){
 case "update-check":return updates.check();
 case "update-install":return updates.install(body.getString("version"));
 case "search":case "lyrics":case "album":case "artist":case "artist-tracks":case "radio":return python(body);
 case "stream":JSONObject result=python(body);if(!result.has("error")){String url=result.getString("url");URL parsed=new URL(url);if(!parsed.getProtocol().equals("https")||!parsed.getHost().endsWith(".googlevideo.com"))throw new IOException("Endereço inválido.");if(streams.size()>12)streams.clear();String token=UUID.randomUUID().toString();streams.put(token,url);result.put("url","https://yuri.local/stream/"+token);}return result;
 case "session-load":return new JSONObject().put("data",read(new File(root,"playback.json")));
 case "session-save":String session=body.getString("data");if(session.length()>2*1024*1024)throw new IOException("Sessão muito grande.");new JSONObject(session);write(new File(root,"playback.json"),session);return ok();
 case "state-load":String saved=read(new File(root,"library.json"));if(saved!=null)try{new JSONObject(saved);}catch(Exception error){saved=read(new File(root,"library.json.bak"));}return new JSONObject().put("data",saved==null?JSONObject.NULL:saved);
 case "state-save":write(new File(root,"library.json"),checkLibrary(body.getString("data")));return ok();
 case "preferences":cacheMB=Math.max(0,Math.min(256,body.optInt("cacheMB",64)));trimCache();return ok();
 case "accent":return ok();
 case "discord":return new JSONObject().put("message","Presença Discord disponível no Windows.");
 case "topmost":return new JSONObject().put("error","Use o miniplayer do Android para ouvir sobre outros aplicativos.");
 case "cache-status":return new JSONObject().put("message",cacheMessage());
 case "cache-clear":for(File f:Objects.requireNonNull(covers.listFiles()))f.delete();return new JSONObject().put("message",cacheMessage());
 case "cover":return cover(body.optString("url"));
 case "downloads":return new JSONObject().put("songs",downloaded());
 case "downloads-folder":return new JSONObject().put("error","No Android, gerencie as músicas na seção Baixadas. Os arquivos ficam no armazenamento privado do app.");
 case "download":String id=body.getString("id");if(!video(id))throw new IOException("Faixa inválida.");body.put("directory",music.getAbsolutePath());JSONObject download=python(body);if(download.has("error"))return download;JSONObject metadata=body.getJSONObject("song");metadata.put("file",download.getString("file"));write(new File(music,id+".json"),metadata.toString());return new JSONObject().put("songs",downloaded());
 case "download-delete":String remove=body.getString("id");if(!video(remove))throw new IOException("Faixa inválida.");for(String ext:new String[]{"json","json.bak","m4a","mp4","webm","opus"})new File(music,remove+"."+ext).delete();return new JSONObject().put("songs",downloaded());
 case "offline":String track=body.getString("id");if(!video(track))throw new IOException("Faixa inválida.");JSONObject data=new JSONObject(Objects.requireNonNull(read(new File(music,track+".json"))));String file=data.getString("file");if(!file.matches("[A-Za-z0-9_-]{11}\\.(m4a|mp4|webm|opus)")||!file.startsWith(track+".")||!new File(music,file).isFile())throw new IOException("Arquivo offline ausente. Baixe novamente.");return new JSONObject().put("url","https://yuri.local/offline/"+file);
 case "sync-off":getPreferences(0).edit().remove("sync").apply();return ok();
 case "sync-read":String uri=getPreferences(0).getString("sync",null);String content=uri==null?null:readUri(Uri.parse(uri));return new JSONObject().put("path",uri==null?JSONObject.NULL:uri).put("data",content==null||content.trim().isEmpty()?JSONObject.NULL:checkLibrary(content));
 case "sync-write":String destination=getPreferences(0).getString("sync",null);if(destination!=null)writeUri(Uri.parse(destination),checkLibrary(body.getString("data")));return ok();
 default:throw new IOException("Pedido inválido.");}}
 JSONObject python(JSONObject body)throws Exception{return new JSONObject(Python.getInstance().getModule("mobile").callAttr("dispatch",body.toString()).toString());}
 JSONArray downloaded(){JSONArray result=new JSONArray();for(File file:Objects.requireNonNull(music.listFiles()))if(file.getName().endsWith(".json"))try{JSONObject data=new JSONObject(read(file));String filename=data.getString("file");if(new File(filename).getName().equals(filename)&&new File(music,filename).isFile())result.put(data);}catch(Exception ignored){}return result;}
 String checkLibrary(String text)throws Exception{if(text.length()>12*1024*1024)throw new IOException("Biblioteca muito grande.");JSONObject data=new JSONObject(text);if(!data.optString("format").equals("yuri-music")||data.optInt("version")!=1)throw new IOException("Backup incompatível.");return text;}
 String read(File file)throws IOException{if(!file.isFile())return null;if(file.length()>16*1024*1024)throw new IOException("Arquivo muito grande.");return new String(Files.readAllBytes(file.toPath()),StandardCharsets.UTF_8);}
 void write(File file,String text)throws IOException{synchronized(diskLock){File temp=new File(file+".tmp");try(FileOutputStream out=new FileOutputStream(temp)){out.write(text.getBytes(StandardCharsets.UTF_8));out.getFD().sync();}if(file.exists())Files.copy(file.toPath(),new File(file+".bak").toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);Files.move(temp.toPath(),file.toPath(),java.nio.file.StandardCopyOption.REPLACE_EXISTING);}}
 String readUri(Uri uri)throws IOException{try(InputStream in=getContentResolver().openInputStream(uri)){return new String(bounded(in,16*1024*1024),StandardCharsets.UTF_8);}}
 void writeUri(Uri uri,String data)throws IOException{try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException("Não foi possível gravar o arquivo.");out.write(data.getBytes(StandardCharsets.UTF_8));}}
 byte[] bounded(InputStream input,int limit)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] block=new byte[8192];int count;while((count=input.read(block))!=-1){if(out.size()+count>limit)throw new IOException("Arquivo muito grande.");out.write(block,0,count);}return out.toByteArray();}
 JSONObject cover(String url)throws Exception{URL parsed=new URL(url);String host=parsed.getHost();if(!parsed.getProtocol().equals("https")||!(host.endsWith(".googleusercontent.com")||host.endsWith(".ggpht.com")||(host.equals("i.ytimg.com")||host.equals("i.scdn.co")||host.equals("mosaic.scdn.co"))))return new JSONObject().put("data","");StringBuilder hash=new StringBuilder();for(byte b:MessageDigest.getInstance("SHA-256").digest(url.getBytes(StandardCharsets.UTF_8)))hash.append(String.format("%02x",b));File file=new File(covers,hash+".cover");byte[] bytes;if(cacheMB>0&&file.isFile()){bytes=Files.readAllBytes(file.toPath());file.setLastModified(System.currentTimeMillis());}else{HttpURLConnection connection=(HttpURLConnection)parsed.openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(15000);connection.setReadTimeout(15000);try{if(connection.getResponseCode()!=200||!connection.getContentType().startsWith("image/"))return new JSONObject().put("data","");try(InputStream in=connection.getInputStream()){bytes=bounded(in,1024*1024);}}finally{connection.disconnect();}if(cacheMB>0){Files.write(file.toPath(),bytes);trimCache();}}return new JSONObject().put("data","data:image/jpeg;base64,"+android.util.Base64.encodeToString(bytes,android.util.Base64.NO_WRAP));}
 void trimCache(){File[] files=covers.listFiles();if(files==null)return;Arrays.sort(files,Comparator.comparingLong(File::lastModified));long size=0;for(File f:files)size+=f.length();for(File f:files){if(size<=cacheMB*1024L*1024)break;size-=f.length();f.delete();}}
 String cacheMessage(){long cover=0,audio=0;for(File f:Objects.requireNonNull(covers.listFiles()))cover+=f.length();for(File f:Objects.requireNonNull(music.listFiles()))audio+=f.length();return String.format(Locale.getDefault(),"Capas: %.1f MB · músicas: %.1f MB",cover/1048576.0,audio/1048576.0);}
 WebResourceResponse remoteStream(WebResourceRequest request)throws Exception{String token=request.getUrl().getLastPathSegment(),url=streams.get(token);if(url==null)throw new IOException();HttpURLConnection connection=(HttpURLConnection)new URL(url).openConnection();connection.setInstanceFollowRedirects(false);connection.setConnectTimeout(15000);connection.setReadTimeout(30000);String range=request.getRequestHeaders().get("Range");if(range!=null&&range.matches("bytes=\\d*-\\d*"))connection.setRequestProperty("Range",range);int status=connection.getResponseCode();if(status!=200&&status!=206){connection.disconnect();throw new IOException();}Map<String,String> headers=new HashMap<>();for(String name:Arrays.asList("Content-Length","Content-Range","Accept-Ranges")){String value=connection.getHeaderField(name);if(value!=null)headers.put(name,value);}headers.put("Cache-Control","no-store");InputStream input=new FilterInputStream(connection.getInputStream()){@Override public void close()throws IOException{super.close();connection.disconnect();}};return new WebResourceResponse(connection.getContentType()==null?"audio/mp4":connection.getContentType().split(";")[0],null,status,status==206?"Partial Content":"OK",headers,input);}
 void picker(int id,String op,JSONObject body){if(dialogOp!=null){answerError(id,"Conclua a seleção de arquivo atual.");return;}dialogRequest=id;dialogOp=op;dialogBody=body;if(op.equals("sync-folder")){new AlertDialog.Builder(this).setTitle("Sincronizar biblioteca").setItems(new String[]{"Escolher biblioteca existente","Criar arquivo de biblioteca"},(dialog,which)->launchPicker(which==0?Intent.ACTION_OPEN_DOCUMENT:Intent.ACTION_CREATE_DOCUMENT)).setOnCancelListener(dialog->{answer(id,new JSONObject());dialogOp=null;}).show();}else launchPicker(op.equals("export")?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT);}
 void launchPicker(String action){Intent intent=new Intent(action);intent.addCategory(Intent.CATEGORY_OPENABLE);intent.setType("application/json");intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);if(action.equals(Intent.ACTION_CREATE_DOCUMENT))intent.putExtra(Intent.EXTRA_TITLE,"yuri-music-library.json");startActivityForResult(intent,10);}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=10||dialogOp==null)return;final int id=dialogRequest;final String op=dialogOp;final JSONObject body=dialogBody;dialogOp=null;if(result!=RESULT_OK||data==null){answer(id,new JSONObject());return;}Uri uri=data.getData();try{if(op.equals("sync-folder")){int flags=data.getFlags()&(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);getContentResolver().takePersistableUriPermission(uri,flags);getPreferences(0).edit().putString("sync",uri.toString()).apply();}jobs.submit(()->{try{JSONObject output=new JSONObject();if(op.equals("export")){writeUri(uri,checkLibrary(body.getString("data")));output.put("saved",true);}else if(op.equals("import"))output.put("data",checkLibrary(readUri(uri)));else{String content=readUri(uri);if(content==null||content.trim().isEmpty())writeUri(uri,"{\"format\":\"yuri-music\",\"version\":1}");output.put("path",uri.toString());}answer(id,output);}catch(Exception error){answerError(id,error.getMessage());}});}catch(Exception error){answerError(id,error.getMessage());}}
 void answer(int id,JSONObject result){if(!destroyed)runOnUiThread(()->{if(!destroyed)web.evaluateJavascript("window.reply("+id+","+result+")",null);});}void answerError(int id,String message){try{answer(id,new JSONObject().put("error",message==null?"Não foi possível concluir.":message));}catch(Exception ignored){}}
 void playback(JSONObject body){if(!body.optBoolean("playing")){PlaybackService.update(this,body);return;}if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},20);PlaybackService.update(this,body);}
 static void command(String action){MainActivity activity=active.get();if(activity!=null&&!activity.destroyed)activity.runOnUiThread(()->activity.web.evaluateJavascript("window.command&&window.command("+JSONObject.quote(action)+")",null));}
 @Override public void onPictureInPictureModeChanged(boolean pip,Configuration config){super.onPictureInPictureModeChanged(pip,config);if(web!=null)web.evaluateJavascript("document.body.classList.toggle('mini',"+pip+")",null);}
 @Override public void onBackPressed(){if(web!=null){web.evaluateJavascript("window.yuriMobileBack?window.yuriMobileBack():(document.querySelector('dialog[open]')?document.querySelector('dialog[open]').close():document.querySelector('[data-page=search]').click())",null);}else super.onBackPressed();}
 @Override protected void onDestroy(){destroyed=true;if(spotifyHost!=null)spotifyHost.dispose();if(isFinishing()){stopService(new Intent(this,PlaybackService.class));if(web!=null)web.destroy();jobs.shutdownNow();}super.onDestroy();}
}
